import React, { useState, useEffect } from "react";
import { Link, useLocation } from "react-router-dom";

export default function Aside() {
  const location = useLocation();
  const [openDropdown, setOpenDropdown] = useState(null);

  // Detect which section is active
  const isCpp = location.pathname.startsWith("/c++");
  const isPhp = location.pathname.startsWith("/php");

  // C Navigation
  const cNavItems = [
    { path: "/introduction", label: "Introduction" },
    { path: "/features", label: "Features" },
    { path: "/pstructure", label: "Program Structure" },
    { path: "/characterset", label: "Character Set" },
    { path: "/printfscanf", label: "Input / Output (I/O)" },
    { path: "/datatype", label: "Data Type" },
    { path: "/comment", label: "Comments" },
    { path: "/token", label: "Tokens" },
    { path: "/operator", label: "Operators" },
    { path: "/typecasting", label: "Type Conversion" },
    { path: "/variable", label: "Variables" },
    { path: "/ifelse", label: "Decision Making" },
    { path: "/switch", label: "Switch Statement" },
    { path: "/loop", label: "Loops" },
    { path: "/breakcontinue", label: "Break & Continue" },
    { path: "/goto", label: "Goto Statement" },
    { path: "/array", label: "Array" },
    { path: "/functions", label: "Functions" },
    { path: "/math", label: "Math" },
    { path: "/string", label: "String" },
    { path: "/pointer", label: "Pointer" },
    { path: "/structure", label: "Structure" },
    { path: "/union", label: "Union" },
    { path: "/enum", label: "Enumeration" },
    { path: "/recursion", label: "Recursion" },
    { path: "/storage", label: "Storage Classes" },
    { path: "/allocation", label: "Dynamic Memory Allocation" },
    { path: "/file", label: "File Handling" },
    {
      label: "Programs",
      children: [
        { path: "/ascii", label: "ASCII" },
        { path: "/star", label: "Star Patterns" },
        { path: "/evenodd", label: "Even or Odd" },
        { path: "/prime", label: "Prime or Not Prime" },
      ],
    },
  ];

  // C++ Navigation
  const cppNavItems = [
    { path: "/c++introduction", label: "Introduction" },
    { path: "/c++cvc", label: "C vs C++" },
    { path: "/c++features", label: "Features" },
    { path: "/c++comments", label: "Comments" },
    { path: "/c++datatype", label: "Data Type" },
    { path: "/c++cincout", label: "Cin / Cout" },
    { path: "/c++variable", label: "Variables" },
    { path: "/c++access", label: "Access Modifiers" },
    { path: "/c++oops", label: "OOPS Concepts" },
    { path: "/c++oopspop", label: "POP vs OOP" },
    { path: "/c++inheritance", label: "Inheritance" },
    { path: "/c++constructor", label: "Constructor" },
    { path: "/c++polymorphism", label: "Polymorphism" },
    { path: "/c++frnds", label: "Friend Function" },
    { path: "/c++overriding", label: "Overriding" },
    { path: "/c++token", label: "Tokens" },
    { path: "/c++operator", label: "Operators" },
    { path: "/c++typecasting", label: "Type Casting" },
    { path: "/c++expression", label: "Expressions" },
    { path: "/c++felse", label: "If / Else" },
    { path: "/c++switch", label: "Switch Statement" },
    { path: "/c++loop", label: "Loops" },
    { path: "/c++breakcontinue", label: "Break & Continue" },
    { path: "/c++goto", label: "Goto Statement" },
    { path: "/c++functions", label: "Functions" },
    { path: "/c++inline", label: "Inline Function" },
    { path: "/c++array", label: "Array" },
    { path: "/c++string", label: "String" },
    { path: "/c++pointer", label: "Pointer" },
    { path: "/c++this", label: "This Pointer" },
    { path: "/c++structure", label: "Structure" },
    { path: "/c++num", label: "Enum" },
    { path: "/c++recursion", label: "Recursion" },
    { path: "/c++storage", label: "Storage Classes" },
    { path: "/c++exceptions", label: "Exceptions" },
    {
      label: "Programs",
      children: [
        { path: "/c++fibonacci", label: "Fibonacci" },
        { path: "/c++evenodd", label: "Even / Odd" },
        { path: "/c++prime", label: "Prime" },
        { path: "/c++palindrome", label: "Palindrome" },
        { path: "/c++factorial", label: "Factorial" },
        { path: "/c++armstrong", label: "Armstrong" },
        { path: "/c++reverse", label: "Reverse" },
        { path: "/c++swapping", label: "Swapping" },
      ],
    },
  ];

  // PHP Navigation
  const phpNavItems = [
    { path: "/phpintroduction", label: "Introduction" },
    { path: "/phpfeatures", label: "Features" },
    { path: "/phpcomments", label: "Comments" },
    { path: "/phpechoprint", label: "Echo / Print" },
    { path: "/phpvariable", label: "Variables" },
    { path: "/php$variable", label: "Global Variables" },
    { path: "/phpdatatype", label: "Data Types" },
    { path: "/phpconstant", label: "Constants" },
    { path: "/phpmagicconst", label: "Magic Constants" },
    { path: "/phpoperator", label: "Operators" },
    { path: "/phpifelse", label: "If / Else" },
    { path: "/phpswitch", label: "Switch Statement" },
    { path: "/phploop", label: "Loops" },
    { path: "/phpbreakcontinue", label: "Break & Continue" },
    { path: "/phpfunction", label: "Functions" },
    { path: "/phprecursive", label: "Recursion" },
    { path: "/phpmath", label: "Math" },
    { path: "/phparray", label: "Array" },
    { path: "/phparrayfunc", label: "Array Functions" },
    { path: "/phpstring", label: "String" },
    { path: "/phpgetpost", label: "GET / POST" },
    { path: "/phpdatetime", label: "Date & Time" },
    { path: "/phpinclude", label: "Include / Require" },
    { path: "/phpfilesystem", label: "File System" },
    { path: "/phpfileupload", label: "File Upload" },
    { path: "/phpcookies", label: "Cookies" },
    { path: "/phpsession", label: "Sessions" },
    { path: "/phpmail", label: "Mail" },
  ];

  const navItems = isPhp ? phpNavItems : isCpp ? cppNavItems : cNavItems;

  // Handle dropdown toggle
  const handleDropdownToggle = (label) => {
    setOpenDropdown((prev) => (prev === label ? null : label));
  };

  // Auto open dropdown if a child is active
  useEffect(() => {
    const activeDropdown = navItems.find(
      (item) =>
        item.children &&
        item.children.some((child) => location.pathname === child.path)
    );
    if (activeDropdown) setOpenDropdown(activeDropdown.label);
  }, [location.pathname]);

  return (
    <aside className="border-start p-3 bg-white shadow-sm rounded-3">
      <ul className="aside-nav nav flex-column">
        {navItems.map((item) =>
          item.children ? (
            <li key={item.label} className="nav-item">
              <button
                className={`nav-link btn btn-link text-start w-100 ${
                  openDropdown === item.label ? "text-dark fw-bold" : "text-muted"
                }`}
                onClick={() => handleDropdownToggle(item.label)}
              >
                {item.label} {openDropdown === item.label ? "▲" : "▼"}
              </button>

              {openDropdown === item.label && (
                <ul className="nav flex-column ms-3">
                  {item.children.map((child) => (
                    <li key={child.path} className="nav-item">
                      <Link
                        to={child.path}
                        className={`nav-link ${
                          location.pathname === child.path
                            ? "text-dark fw-bold"
                            : "text-muted"
                        }`}
                      >
                        {child.label}
                      </Link>
                    </li>
                  ))}
                </ul>
              )}
            </li>
          ) : (
            <li key={item.path} className="nav-item">
              <Link
                to={item.path}
                className={`nav-link ${
                  location.pathname === item.path
                    ? "text-dark fw-bold"
                    : "text-muted"
                }`}
              >
                {item.label}
              </Link>
            </li>
          )
        )}
      </ul>
    </aside>
  );
}
