import React, { useEffect, useState } from "react";
import { useNavigate, useLocation, Link } from "react-router-dom";
import { signOut } from "firebase/auth";
import { auth } from "../../firebaseConfig";
import AOS from "aos";
import "aos/dist/aos.css";

export default function Header() {
  const navigate = useNavigate();
  const location = useLocation();
  const [userEmail, setUserEmail] = useState("");
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const storedEmail = sessionStorage.getItem("userEmail");
    if (!storedEmail) {
      navigate("/");
    } else {
      setUserEmail(storedEmail);
    }

    AOS.init({ duration: 800, easing: "slide", once: true });
  }, [navigate]);

  const handleLogout = async () => {
    try {
      await signOut(auth);
    } catch (err) {
      console.error("Error during sign out:", err);
    } finally {
      sessionStorage.removeItem("userEmail");
      navigate("/");
    }
  };

  return (
    <header className="site-navbar py-3 shadow-sm" role="banner">
      <div className="container-fluid">
        <div className="d-flex justify-content-between align-items-center">
          {/* Logo */}
          <div data-aos="fade-down">
            <h1 className="mb-0">
              <Link
                to="/dashboard"
                className="text-white h2 mb-0 text-decoration-none"
              >
                Tutorial
              </Link>
            </h1>
          </div>

          {/* Desktop Menu */}
          <nav
            className="site-navigation d-none d-xl-block text-center"
            data-aos="fade-down"
            role="navigation"
          >
            <ul className="site-menu d-flex gap-4 list-unstyled mb-0">
              <li className={location.pathname === "/dashboard" ? "active" : ""}>
                <Link to="/dashboard">Home</Link>
              </li>
              <li className={location.pathname === "/about" ? "active" : ""}>
                <Link to="/about">About</Link>
              </li>
              <li className={location.pathname === "/contact" ? "active" : ""}>
                <Link to="/contact">Contact</Link>
              </li>
            </ul>
          </nav>

          {/* Right Section */}
          <div className="d-flex align-items-center gap-3" data-aos="fade-down">
            <button
              onClick={handleLogout}
              className="btn btn-sm text-light fw-semibold align-items-center gap-2"
            >
              {userEmail || "Logout"} <i className="fas fa-sign-out-alt text-danger"></i>
            </button>

            {/* Mobile Menu Button */}
            <button
              className="btn text-white d-xl-none"
              onClick={() => setMenuOpen(!menuOpen)}
            >
              <i
                className={`fas ${menuOpen ? "fa-times" : "fa-bars"} fa-lg`}
              ></i>
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Dropdown Menu */}
      {menuOpen && (
        <div className="mobile-menu p-3" data-aos="fade-down">
          <ul className="list-unstyled mb-3">
            <li className="py-2">
              <Link
                to="/dashboard"
                onClick={() => setMenuOpen(false)}
                className="text-white text-decoration-none"
              >
                Home
              </Link>
            </li>
            <li className="py-2">
              <Link
                to="/about"
                onClick={() => setMenuOpen(false)}
                className="text-white text-decoration-none"
              >
                About
              </Link>
            </li>
            <li className="py-2">
              <Link
                to="/contact"
                onClick={() => setMenuOpen(false)}
                className="text-white text-decoration-none"
              >
                Contact
              </Link>
            </li>
          </ul>

          {/* ✅ Email/Logout Button in Mobile Menu */}
          <button
            onClick={() => {
              handleLogout();
              setMenuOpen(false);
            }}
            className="btn btn-sm text-light fw-semibold d-flex align-items-center gap-2"
          >
            {userEmail}
            <i className="pl-2 fas fa-sign-out-alt text-danger"></i>
          </button>

        </div>
      )}
    </header>
  );
}
