import React, { useEffect, useRef, useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import Sidebar from "../Include/Sidebar";
import Footer from "../Include/Footer";
import Aside from "../Include/Aside";
import '../Styles/GlobalStyles';
import ForImg from '../../Images/data/for.jpg';
import WhileImg from '../../Images/data/while.jpg';
import DowhileImg from '../../Images/data/dowhile.jpg';

export default function Loop() {
    const [email, setEmail] = useState("");
    const [showAside, setShowAside] = useState(false);
    const [showSidebar, setShowSidebar] = useState(false);
    const [sidebarPinned, setSidebarPinned] = useState(false);

    const navigate = useNavigate();
    const sidebarRef = useRef(null);
    const asideRef = useRef(null);

    // ✅ Session check
    useEffect(() => {
        const storedEmail = sessionStorage.getItem("userEmail");
        if (!storedEmail) {
            navigate("/");
        } else {
            setEmail(storedEmail);
        }
    }, [navigate]);

    // ✅ Logout
    const handleLogout = () => {
        sessionStorage.removeItem("userEmail");
        navigate("/");
    };

    // ✅ Toggle handlers
    const toggleSidebar = () => setShowSidebar((prev) => !prev);
    const togglePinSidebar = () => setSidebarPinned((prev) => !prev);
    const toggleAside = () => setShowAside((prev) => !prev);

    // ✅ Close handlers
    const closeSidebar = () => setShowSidebar(false);
    const closeAside = () => setShowAside(false);

    // ✅ Click outside to close (both)
    useEffect(() => {
        const handleClickOutside = (e) => {
            // Close Right Aside
            if (
                asideRef.current &&
                !asideRef.current.contains(e.target) &&
                !e.target.closest(".toggle-aside-btn")
            ) {
                setShowAside(false);
            }

            // Close Left Sidebar (on mobile)
            if (
                sidebarRef.current &&
                !sidebarRef.current.contains(e.target) &&
                !e.target.closest(".toggle-sidebar-btn")
            ) {
                setShowSidebar(false);
            }
        };

        document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
    }, []);

    return (
        <div
        className={`page-wrapper light-theme 
            ${showSidebar ? "toggled" : ""} 
            ${sidebarPinned ? "pinned" : ""}`}
    >
            <div ref={sidebarRef}>
                <Sidebar
                    sidebarPinned={sidebarPinned}
                    togglePinSidebar={togglePinSidebar}
                />
            </div>

            <main className="page-content">

                <div className="container-fluid">
                    {/* Top Bar */}
                    <div className="d-flex justify-content-between align-items-center flex-wrap p-3 border-bottom">
                        {/* Left Sidebar Toggle */}
                        <div className="d-flex align-items-center">
                            <button
                                id="toggle-sidebar"
                                className="btn rounded-0 p-2 p-md-3 me-2"
                                onClick={toggleSidebar}
                            >
                                <i className="fas fa-bars"></i>
                            </button>

                            {/* Breadcrumb (Hidden on Small Screens) */}
                            <nav aria-label="breadcrumb" className="d-none d-md-block">
                                <ol className="breadcrumb m-0">
                                    <li className="breadcrumb-item">
                                        <Link to="/dashboard">Home</Link>
                                    </li>
                                    <li className="breadcrumb-item active" aria-current="page">
                                        Loops
                                    </li>
                                </ol>
                            </nav>
                        </div>
                        <div className="d-flex align-items-center">
                            <button
                                onClick={handleLogout}
                                className="btn btn-link text-dark fw-semibold p-0 me-2"
                            >
                                {email}
                            </button>

                            {/* Right Sidebar Toggle (Visible Only on Mobile) */}
                            <button
                                className="btn rounded-0 p-2 p-md-3 d-md-none"
                                onClick={toggleAside}
                            >
                                <i className="fas fa-bars"></i>
                            </button>
                        </div>
                    </div>

                    {/* Main Content */}
                    <div className="row p-lg-4">
                    <article className="main-content col-md-9 pr-lg-5">
                        
                        <h1 className="mb-2 mt-3">Loops</h1>
                        
                        <p>In loop, a loop is a sequence of instructions that is repeated until a certain condition is reached.</p>
						<p>There are mainly two types of loops:</p>
						<ul>
							<li>Entry Controlled loops: In this type of loops the test condition is tested before entering the loop body. For Loop and While Loop are entry controlled loops.</li>
							
							<li>Exit Controlled Loops: In this type of loops the test condition is tested or evaluated at the end of loop body. Therefore, the loop body will execute atleast once, irrespective of whether the test condition is true or false. do – while loop is exit controlled loop.</li>
						</ul>
                        <hr className="my-5"/>
						<h1 className="mb-2 mt-3">for Loop</h1>
                        <p>In for loop, a loop variable is used to control the loop. First initialize this loop variable to some value, then check whether this variable is less than or greater than counter value. If statement is true, then loop body is executed and loop variable gets updated . Steps are repeated till exit condition comes.</p>
						<figure className="code-block">
                                <pre><div className="text-muted mb-2">{`<!-- Syntax -->`}</div>
                                    {`for (initialization expr; test expr; update expr)
{    
     // body of the loop
     // statements we want to execute
}`}</pre></figure>
						<img src={ForImg} alt="For"/>
                        <figure className="code-block">
                                <pre><div className="text-muted mb-2">{`<!-- Example -->`}</div>
                                    {`#include<stdio.h>
#include<conio.h> 
void main() 						
{ 
    int i=0; 
    for (i = 1; i <= 10; i++) 
    { 
        printf( "Hello World\\n");     
    } 
    getch(); 
} 
Output:

Hello World
Hello World
Hello World
Hello World
Hello World
Hello World
Hello World
Hello World
Hello World
Hello World`}</pre></figure>
						<hr className="my-5"/>
						<h1 className="mb-2 mt-3">While Loop</h1>
                        <p>While studying for loop we have seen that the number of iterations is known beforehand, i.e. the number of times the loop body is needed to be executed is known to us. while loops are used in situations where we do not know the exact number of iterations of loop beforehand. The loop execution is terminated on the basis of test condition.</p>
						<figure className="code-block">
                                <pre><div className="text-muted mb-2">{`<!-- Syntax -->`}</div>
                                    {`initialization expression;
while (test_expression)
{
   // statements
 
  update_expression;
}`}</pre></figure>
						<img src={WhileImg} alt="While"/>
                        <figure className="code-block">
                                <pre><div className="text-muted mb-2">{`<!-- Example -->`}</div>
                                    {`#include<stdio.h>
#include<conio.h> 
void main() {
  int i = 1; 
  // test expression 
  while (i < 6) 
  { 
    printf( "Hello World\\n");     
    // update expression 
    i++; 
  } 
  getch(); 
}
 
Output:

Hello World
Hello World
Hello World
Hello World
Hello World`}</pre></figure>
						<hr className="my-5"/>
						<h1 className="mb-2 mt-3">do while loop</h1>
                        <p>In do while loops also the loop execution is terminated on the basis of test condition. The main difference between do while loop and while loop is in do while loop the condition is tested at the end of loop body, i.e do while loop is exit controlled whereas the other two loops are entry controlled loops.</p>
						<p><b>Note:</b> In do while loop the loop body will execute at least once irrespective of test condition..</p>
						<figure className="code-block">
                                <pre><div className="text-muted mb-2">{`<!-- Syntax -->`}</div>
                                    {`initialization expression;
do
{
   // statements

   update_expression;
} while (test_expression);`}</pre></figure>
						<img src={DowhileImg} alt="DoWhile"/>
                        <figure className="code-block">
                                <pre><div className="text-muted mb-2">{`<!-- Example -->`}</div>
                                    {`#include<stdio.h>
#include<conio.h> 
void main() 						
{ 
    clrscr();
    int i = 2; // Initialization expression 
    do
    { 
        // loop body 
        printf( "Hello World\\n");     
  
        // update expression 
        i++; 
  
    }  while (i < 1);   // test expression 
    getch(); 
} 
Output:

Hello World`}</pre></figure>
                            <hr className="my-5" />
                            <Footer />
                        </article>

                        <div className="col-12 col-md-3 d-none d-md-block">
                            <Aside />
                        </div>

                        {/* RIGHT ASIDE (Mobile) */}
                        <div
                            ref={asideRef}
                            className={`aside-wrapper d-md-none ${showAside ? "show" : ""}`}
                        >
                            <Aside />
                        </div>

                        {/* OVERLAYS */}
                        {showAside && <div className="overlay" onClick={closeAside}></div>}
                        {showSidebar && <div className="overlay" onClick={closeSidebar}></div>}
                    </div>
                </div>
            </main>
        </div>
    )
}
