// src/Components/Auth/ForgotPassword.js
import React, { useState } from "react";
import { sendPasswordResetEmail } from "firebase/auth";
import { auth } from "../../firebaseConfig";
import { Link } from "react-router-dom";
import "./Login.css";

export default function ForgotPassword() {
  const [email, setEmail] = useState("");
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");

  const handleReset = async (e) => {
    e.preventDefault();
    setMessage("");
    setError("");

    try {
      await sendPasswordResetEmail(auth, email);
      setMessage("✅ Password reset link sent to your email!");
      setEmail("");
    } catch (err) {
      setError(err.message.replace("Firebase:", "").trim());
    }
  };

  return (
    <div className="login-reg-panel d-flex justify-content-center align-items-center">
      <div className="white-panel text-center" style={{ width: "400px", padding: "30px" }}>
        <h2>Forgot Password</h2>
        <p className="text-muted">Enter your email to reset password</p>
        {message && <div className="alert alert-success py-1">{message}</div>}
        {error && <div className="alert alert-danger py-1">{error}</div>}

        <form onSubmit={handleReset}>
          <div className="form-group mb-3">
            <input
              type="email"
              name="email"
              className="form-control"
              placeholder="Enter your registered email"
              value={email}
              required
              onChange={(e) => setEmail(e.target.value)}
            />
          </div>
          <button type="submit" className="btn btn-danger w-100">
            Send Reset Link
          </button>
        </form>

        <div className="mt-3">
          <Link to="/login" className="text-decoration-none">
            ← Back to Login
          </Link>
        </div>
      </div>
    </div>
  );
}
