import React, { useEffect, useRef, useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import Sidebar from "../Include/Sidebar";
import Footer from "../Include/Footer";
import Aside from "../Include/Aside";
import '../Styles/GlobalStyles';

export default function CCArray() {
    const [email, setEmail] = useState("");
    const [showAside, setShowAside] = useState(false);
    const [showSidebar, setShowSidebar] = useState(false);
    const [sidebarPinned, setSidebarPinned] = useState(false);

    const navigate = useNavigate();
    const sidebarRef = useRef(null);
    const asideRef = useRef(null);

    // ✅ Session check
    useEffect(() => {
        const storedEmail = sessionStorage.getItem("userEmail");
        if (!storedEmail) {
            navigate("/");
        } else {
            setEmail(storedEmail);
        }
    }, [navigate]);

    // ✅ Logout
    const handleLogout = () => {
        sessionStorage.removeItem("userEmail");
        navigate("/");
    };

    // ✅ Toggle handlers
    const toggleSidebar = () => setShowSidebar((prev) => !prev);
    const togglePinSidebar = () => setSidebarPinned((prev) => !prev);
    const toggleAside = () => setShowAside((prev) => !prev);

    // ✅ Close handlers
    const closeSidebar = () => setShowSidebar(false);
    const closeAside = () => setShowAside(false);

    // ✅ Click outside to close (both)
    useEffect(() => {
        const handleClickOutside = (e) => {
            // Close Right Aside
            if (
                asideRef.current &&
                !asideRef.current.contains(e.target) &&
                !e.target.closest(".toggle-aside-btn")
            ) {
                setShowAside(false);
            }

            // Close Left Sidebar (on mobile)
            if (
                sidebarRef.current &&
                !sidebarRef.current.contains(e.target) &&
                !e.target.closest(".toggle-sidebar-btn")
            ) {
                setShowSidebar(false);
            }
        };

        document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
    }, []);

    return (
        <div
        className={`page-wrapper light-theme 
            ${showSidebar ? "toggled" : ""} 
            ${sidebarPinned ? "pinned" : ""}`}
    >
            <div ref={sidebarRef}>
                <Sidebar
                    sidebarPinned={sidebarPinned}
                    togglePinSidebar={togglePinSidebar}
                />
            </div>

            <main className="page-content">

                <div className="container-fluid">
                    {/* Top Bar */}
                    <div className="d-flex justify-content-between align-items-center flex-wrap p-3 border-bottom">
                        {/* Left Sidebar Toggle */}
                        <div className="d-flex align-items-center">
                            <button
                                id="toggle-sidebar"
                                className="btn rounded-0 p-2 p-md-3 me-2"
                                onClick={toggleSidebar}
                            >
                                <i className="fas fa-bars"></i>
                            </button>

                            {/* Breadcrumb (Hidden on Small Screens) */}
                            <nav aria-label="breadcrumb" className="d-none d-md-block">
                                <ol className="breadcrumb m-0">
                                    <li className="breadcrumb-item">
                                        <Link to="/dashboard">Home</Link>
                                    </li>
                                    <li className="breadcrumb-item active" aria-current="page">
                                        Array
                                    </li>
                                </ol>
                            </nav>
                        </div>
                        <div className="d-flex align-items-center">
                            <button
                                onClick={handleLogout}
                                className="btn btn-link text-dark fw-semibold p-0 me-2"
                            >
                                {email}
                            </button>

                            {/* Right Sidebar Toggle (Visible Only on Mobile) */}
                            <button
                                className="btn rounded-0 p-2 p-md-3 d-md-none"
                                onClick={toggleAside}
                            >
                                <i className="fas fa-bars"></i>
                            </button>
                        </div>
                    </div>
                    {/* Main Content */}
                    <div className="row p-lg-4">
                        <article className="main-content col-md-9 pr-lg-5">

                            <h1 className="mb-2 mt-3">Array</h1>

                            <p>An array is a collection of items stored at contiguous memory locations and elements can be accessed randomly using indices of an array. They are used to store similar type of elements as in the data type must be the same for all elements. They can be used to store collection of primitive data types such as int, float, double, char, etc of any particular type.</p>
                            <p>Declaration of C Array</p>
                            <figure className="code-block">
                                <pre><div className="text-muted mb-2">{`<!-- Syntax -->`}</div>
                                    {`type arrayName [ arraySize ];

int marks[5]; `}</pre></figure>
                            <hr className="my-5" />
                            <h1 className="mb-2 mt-3">Types of Array</h1>
                            <p>There are two types of array.</p>
                            <ol>
                                <li>One dimensional array</li>
                                <li>Multi dimensional array</li>
                            </ol>
                            <hr className="my-5" />
                            <h1 className="mb-2 mt-3">ONE DIMENSIONAL ARRAY</h1>
                            <p>single dimensional arrays are used to store list of values of same datatype. In other words, single dimensional arrays are used to store a row of values. In single dimensional array, data is stored in linear form. Single dimensional arrays are also called as one-dimensional arrays, Linear Arrays or simply 1-D Arrays.</p>
                            <figure className="code-block">
                                <pre><div className="text-muted mb-2">{`<!-- Syntax -->`}</div>
                                    {`data-type arr_name[array_size];`}</pre></figure>
                            <figure className="code-block">
                                <pre><div className="text-muted mb-2">{`<!-- Example -->`}</div>
                                    {`#include<iostream.h>
#include<conio.h> 
void main() {
  int arr[5]={10, 0, 20, 0, 30};  //creating and initializing array    
  //traversing array    
  for (int i = 0; i < 5; i++)    
  {    
    cout<<arr[i]<<"\\n";    
  }    
  getch(); 
}

Output:

10
0
20
0
30`}</pre></figure>
                            <hr className="my-5" />
                            <h1 className="mb-2 mt-3">TWO DIMENSIONAL ARRAY</h1>
                            <p>An array of arrays is called as multi dimensional array. In simple words, an array created with more than one dimension (size) is called as multi dimensional array. Multi dimensional array can be of two dimensional array or three dimensional array or four dimensional array or more...</p>
                            <p>Most popular and commonly used multi dimensional array is two dimensional array. The 2-D arrays are used to store data in the form of table. We also use 2-D arrays to create mathematical matrices.</p>
                            <figure className="code-block">
                                <pre><div className="text-muted mb-2">{`<!-- Syntax -->`}</div>
                                    {`data_type array_name[num_of_rows][num_of_column];`}</pre></figure>
                            <figure className="code-block">
                                <pre><div className="text-muted mb-2">{`<!-- Example -->`}</div>
                                    {`#include<iostream.h>
#include<conio.h> 
void main() {
  int arr[5]={10, 0, 20, 0, 30};  //creating and initializing array    
  //traversing array    
  for (int i = 0; i < 5; i++)    
  {    
    cout<<arr[i]<<"\\n";    
  }    
  getch(); 
}

Output:

10
0
20
0
30`}</pre></figure>
                            <hr className="my-5" />
                            <h1 className="mb-2 mt-3">Multi DIMENSIONAL ARRAY</h1>
                            <p>The multidimensional array is also known as rectangular arrays in C++. It can be two dimensional or three dimensional. The data is stored in tabular form (row ∗ column) which is also known as matrix.</p>
                            <figure className="code-block">
                                <pre><div className="text-muted mb-2">{`<!-- Syntax -->`}</div>
                                    {`data_type array_name[num_of_rows][num_of_column];`}</pre></figure>
                            <figure className="highlight">
                                <pre><div className="text-muted mb-2">{`<!-- Example -->`}</div>
                                    {`#include<iostream.h> 
#include<conio.h> 
void main() 						
{ 
  int test[3][3];  //declaration of 2D array   
  test[0][0]=5;  //initialization   
  test[0][1]=10;   
  test[1][1]=15;  
  test[1][2]=20;  
  test[2][0]=30;  
  test[2][2]=10;  
  //traversal    
  for(int i = 0; i < 3; ++i)  
  {  
    for(int j = 0; j < 3; ++j)  
    {  
      cout<< test[i][j]<<" ";  
    }  
    cout<<"\\n"; //new line at each row   
  }  
  getch(); 
} 
Output:

5 10 0 
0 15 20 
30 0 10 `}

                                </pre></figure>
                            <hr className="my-5" />
                            <h1 className="mb-2 mt-3">Passing arrays to functions</h1>
                            <p>In C++, to reuse the array logic, we can create function. To pass array to function in C++, we need to provide only array name.</p>
                            <figure className="code-block">
                                <pre><div className="text-muted mb-2">{`<!-- Example -->`}</div>
                                    {`#include<iostream.h>
#include<conio.h> 
void printArray(int arr[5]);  
int main()  
{  
  int arr1[5] = { 10, 20, 30, 40, 50 };    
  int arr2[5] = { 5, 15, 25, 35, 45 };    
  printArray(arr1); //passing array to function    
  printArray(arr2);  
}  
void printArray(int arr[5])  
{  
  cout << "Printing array elements:" << endl;  
  for (int i = 0; i < 5; i++)  
  {  
    cout<<arr[i]<<"\\n";    
  }  
}  

Output:

Printing array elements:                                                              
10                                                                                    
20                                                                                    
30                                                                                    
40                                                                                    
50                                                                                    
Printing array elements:                                                              
5                                                                                     
15                                                                                    
25                                                                                    
35                                                                                    
45
`}
                                </pre>
                            </figure>

                            <hr className="my-5" />
                            <Footer />
                        </article>

                        <div className="col-12 col-md-3 d-none d-md-block">
                            <Aside />
                        </div>

                        {/* RIGHT ASIDE (Mobile) */}
                        <div
                            ref={asideRef}
                            className={`aside-wrapper d-md-none ${showAside ? "show" : ""}`}
                        >
                            <Aside />
                        </div>

                        {/* OVERLAYS */}
                        {showAside && <div className="overlay" onClick={closeAside}></div>}
                        {showSidebar && <div className="overlay" onClick={closeSidebar}></div>}
                    </div>
                </div>
            </main>
        </div>
    )
}
