import React, { useEffect, useRef, useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import Sidebar from "../Include/Sidebar";
import Footer from "../Include/Footer";
import Aside from "../Include/Aside";
import '../Styles/GlobalStyles';

export default function Pstructure() {
    const [email, setEmail] = useState("");
    const [showAside, setShowAside] = useState(false);
    const [showSidebar, setShowSidebar] = useState(false);
    const [sidebarPinned, setSidebarPinned] = useState(false);

    const navigate = useNavigate();
    const sidebarRef = useRef(null);
    const asideRef = useRef(null);

    // ✅ Session check
    useEffect(() => {
        const storedEmail = sessionStorage.getItem("userEmail");
        if (!storedEmail) {
            navigate("/");
        } else {
            setEmail(storedEmail);
        }
    }, [navigate]);

    // ✅ Logout
    const handleLogout = () => {
        sessionStorage.removeItem("userEmail");
        navigate("/");
    };

    // ✅ Toggle handlers
    const toggleSidebar = () => setShowSidebar((prev) => !prev);
    const togglePinSidebar = () => setSidebarPinned((prev) => !prev);
    const toggleAside = () => setShowAside((prev) => !prev);

    // ✅ Close handlers
    const closeSidebar = () => setShowSidebar(false);
    const closeAside = () => setShowAside(false);

    // ✅ Click outside to close (both)
    useEffect(() => {
        const handleClickOutside = (e) => {
            // Close Right Aside
            if (
                asideRef.current &&
                !asideRef.current.contains(e.target) &&
                !e.target.closest(".toggle-aside-btn")
            ) {
                setShowAside(false);
            }

            // Close Left Sidebar (on mobile)
            if (
                sidebarRef.current &&
                !sidebarRef.current.contains(e.target) &&
                !e.target.closest(".toggle-sidebar-btn")
            ) {
                setShowSidebar(false);
            }
        };

        document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
    }, []);

    return (
        <div
            className={`page-wrapper light-theme 
            ${showSidebar ? "toggled" : ""} 
            ${sidebarPinned ? "pinned" : ""}`}
        >
            <div ref={sidebarRef}>
                <Sidebar
                    sidebarPinned={sidebarPinned}
                    togglePinSidebar={togglePinSidebar}
                />
            </div>

            <main className="page-content">

                <div className="container-fluid">
                    {/* Top Bar */}
                    <div className="d-flex justify-content-between align-items-center flex-wrap p-3 border-bottom">
                        {/* Left Sidebar Toggle */}
                        <div className="d-flex align-items-center">
                            <button
                                id="toggle-sidebar"
                                className="btn rounded-0 p-2 p-md-3 me-2"
                                onClick={toggleSidebar}
                            >
                                <i className="fas fa-bars"></i>
                            </button>

                            {/* Breadcrumb (Hidden on Small Screens) */}
                            <nav aria-label="breadcrumb" className="d-none d-md-block">
                                <ol className="breadcrumb m-0">
                                    <li className="breadcrumb-item">
                                        <Link to="/dashboard">Home</Link>
                                    </li>
                                    <li className="breadcrumb-item active" aria-current="page">
                                        Program Structure
                                    </li>
                                </ol>
                            </nav>
                        </div>
                        <div className="d-flex align-items-center">
                            <button
                                onClick={handleLogout}
                                className="btn btn-link text-dark fw-semibold p-0 me-2"
                            >
                                {email}
                            </button>

                            {/* Right Sidebar Toggle (Visible Only on Mobile) */}
                            <button
                                className="btn rounded-0 p-2 p-md-3 d-md-none"
                                onClick={toggleAside}
                            >
                                <i className="fas fa-bars"></i>
                            </button>
                        </div>
                    </div>

                    {/* Main Content */}
                    <div className="row p-lg-4">
                        <article className="main-content col-md-9 pr-lg-5">

                            <h1 className="mb-2 mt-3">Program Structure</h1>

                            <p>Structure of C program includes the following : Documentation, Preprocessor, Constant Declaration, Global Declaration, main(), Subprograms.</p>

                            <figure className="code-block">
                                <pre>
                                    {`Documentation
----------------------------------

Preprocessor
----------------------------------

Constant Declaration
----------------------------------

Global Declaration
----------------------------------

main()
{
    // body of main()
}
----------------------------------

Subprograms
Function1()
Function2()
|
|
FunctionN()
`}
                                </pre>
                            </figure>

                            <hr className="my-5" />
                            <h3 className="font-weight-bold mb-2">
                                Note:
                            </h3>
                            <ul>
                                <li>Documentation may includes the information about the program, author, date of creation of program, etc. as comments.</li>
                                <li>Preprocessor tells the compiler to execute function, defines in header file, before the execution of main().</li>
                                <li>In Constant Declaration section, we declare constant variables, we can't change the value of constant variables throughout the program and we must initialize constant variables with declaration.</li>
                                <li>In Global Declaration section, we declare global variables, global variables are those variables that can be accessed by all function in a program.</li>
                                <li>main() is the first function to get executed. The main() serves as the starting point for program execution. It usually controls program execution by directing the calls to other functions in the program. A program usually stops executing at the end of main.The execution of main() begins with opening brace and ends with closing brace.</li>
                                <li>The subprogram section consists all the definition of user-defined functions that are called in the main().</li>
                            </ul>
                            <hr className="my-5" />
                            <Footer />
                        </article>

                        <div className="col-12 col-md-3 d-none d-md-block">
                            <Aside />
                        </div>

                        {/* RIGHT ASIDE (Mobile) */}
                        <div
                            ref={asideRef}
                            className={`aside-wrapper d-md-none ${showAside ? "show" : ""}`}
                        >
                            <Aside />
                        </div>

                        {/* OVERLAYS */}
                        {showAside && <div className="overlay" onClick={closeAside}></div>}
                        {showSidebar && <div className="overlay" onClick={closeSidebar}></div>}
                    </div>
                </div>
            </main>
        </div>
    )
}
